import{_ as o,o as d,c as t,a2 as n}from"./chunks/framework.DhQimoSI.js";const p=JSON.parse('{"title":"Definitions","description":"","frontmatter":{},"headers":[],"relativePath":"welcome/definitions.md","filePath":"welcome/definitions.md"}'),a={name:"welcome/definitions.md"};function i(s,e,c,r,h,l){return d(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="definitions" tabindex="-1">Definitions <a class="header-anchor" href="#definitions" aria-label="Permalink to &quot;Definitions&quot;">​</a></h1><p>The words these docs use, and what each one means in Mosaic.</p><dl><dt>Archive</dt><dd>A <code>.tsr</code> file. A zip holding <code>index.json</code> and one <code>&lt;type&gt;.ndjson</code> table per component type. It is what gets exchanged, published and imported.</dd><dt>Source document</dt><dd>A <code>.mosaic.json</code> file. One readable, diffable JSON document holding the index plus the component rows. <code>mosaic pack</code> turns it into an archive. See <a href="/mosaic/dist/docs/tools/pack">Packing a dataset</a>.</dd><dt>Index file</dt><dd><code>index.json</code> inside an archive (<code>MosaicIndexFile</code>). It holds a <code>header</code>, the <code>imports</code>, the <code>componentTables</code> and the <code>sections</code>. See <a href="/mosaic/dist/docs/standard/file/format">The format</a>.</dd><dt>Section</dt><dd>One layer of edits. It has a provenance header (author, timestamp, application and a message) and the nodes it contributes. The sections of a file are a list, so a dataset is a history of edits rather than a single snapshot. A later section wins over an earlier one.</dd><dt>Node</dt><dd>Something with an id (a <code>uuid</code>) and a list of component references. A node has no value of its own: everything it is comes from its components.</dd><dt>Component</dt><dd>A typed piece of data, such as a transform, a mesh or a property set. Its type is named by an <code>x-mosaic-id</code> like <code>core::transform</code> or <code>khronos::gltf::accessor</code>, and it is described by a JSON Schema.</dd><dt>Component reference</dt><dd>How a node carries a component: <code>{ &quot;type&quot;, &quot;id&quot;, &quot;index&quot;?, &quot;operation&quot;? }</code>. <code>type</code> names the component type. <code>id</code> names this reference within the node. <code>index</code> is the row in that type&#39;s table, and <code>operation</code> is <code>VALUE</code>, <code>DELETE</code> or <code>PASS_THROUGH</code>.</dd><dt>Component table</dt><dd>All the values of one component type in an archive, one row per line of NDJSON (or a Parquet file), with the schema of its rows beside it. A reference&#39;s <code>index</code> points into it.</dd><dt>Value-less component</dt><dd>A component whose reference carries no row (<code>index</code> is <code>-1</code>, the default). Everything it says is in the reference <code>id</code>. <code>core::child</code>, <code>core::name</code> and <code>core::inherit</code> work this way. See <a href="/mosaic/dist/docs/standard/core-components">Core components</a>.</dd><dt>Operation</dt><dd>What a reference does to the value a node already has: <code>VALUE</code> sets it (the default), <code>DELETE</code> unsets it, and <code>PASS_THROUGH</code> leaves the inherited value alone.</dd><dt>Import</dt><dd>A reference from one archive to another, by URI, optionally pinned with an <code>integrity</code> hash. An imported archive layers <em>underneath</em> the one that imports it, as an older section would.</dd><dt>Federation</dt><dd>Merging archives into one. Their component tables are laid end to end, references are shifted to match, and nodes that share an id merge rather than duplicate.</dd><dt>Composition</dt><dd>Reading a dataset the way a consumer sees it: imports merged, sections collapsed, inheritance expanded and child links followed. <code>mosaic compose</code> writes the result as a GLB. See <a href="/mosaic/dist/docs/tools/compose">Composing a GLB</a>.</dd><dt>Inheritance (is-a)</dt><dd>A <code>core::inherit</code> link. Composing gives the node every component of the node it names, except the ones it carries itself under the same reference <code>id</code>.</dd><dt>Hierarchy (child)</dt><dd>A <code>core::child</code> link. It hangs another node beneath this one. Naming a node from several parents places it several times, and the copies share their geometry.</dd><dt>Tessera</dt><dd>One model kept by the <a href="/mosaic/dist/docs/sdk/http-api">HTTP API</a>, a tile of the mosaic, with a history of versions. An archive published to the API becomes a version of a tessera.</dd><dt>Version</dt><dd>One published state of a tessera. A new version must follow the one the tessera is on, or it is answered with <code>OUT_OF_DATE</code>.</dd><dt>Namespace</dt><dd>The prefix of a component type: <code>core::</code> for the format&#39;s own components, <code>khronos::gltf::</code> for geometry derived from glTF, <code>w3c::</code> for SVG and <code>ifc4::</code> for IFC. Anyone can define their own, such as <code>acme::geometry::wall</code>.</dd></dl>',3)])])}const f=o(a,[["render",i]]);export{p as __pageData,f as default};
